def installment_options(amount, max_months=12, min_amount=50000):
    return ["일시불"] + ([f"{m}개월" for m in range(2, max_months + 1)] if amount >= min_amount else [])

print(installment_options(12900))               # ['일시불']
print(installment_options(129000, max_months=6)) # ['일시불', '2개월', '3개월', '4개월', '5개월', '6개월']
